p=Path('/mnt/data/mda_v015/src/engine.cpp');s=p.read_text()
s=s.replace('static constexpr int kFadeSteps = 240; // 4.0 seconds at 60 fade updates per second', 'static constexpr int kFadeSteps = 40; // Sonic 3K: $28 (40) fade steps\nstatic constexpr int kSamplesPerFadeStep = 4410; // six 60 Hz ticks = 0.1 s at 44.1 kHz')
